class Solution {
public:
    int countDifferentSubsequenceGCDs(vector<int>& nums) {
        unordered_set<int> gs;
        for (int x : nums) {
            unordered_set<int> nxt;
            for (int g : gs) nxt.insert(gcd(g, x));
            nxt.insert(x);
            gs.insert(nxt.begin(), nxt.end());
        }
        return gs.size();
    }
};

