class Solution {
    public int countDifferentSubsequenceGCDs(int[] nums) {
        Set<Integer> gs = new HashSet<>();
        for (int x : nums) {
            Set<Integer> nxt = new HashSet<>();
            for (int g : gs) nxt.add(gcd(g, x));
            nxt.add(x);
            gs.addAll(nxt);
        }
        return gs.size();
    }

    private int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }
}

