import math


class Solution:
    def countDifferentSubsequenceGCDs(self, nums):
        max_v = max(nums)
        present = [False] * (max_v + 1)
        for x in nums:
            present[x] = True
        ans = 0
        for g in range(1, max_v + 1):
            cur = 0
            for m in range(g, max_v + 1, g):
                if present[m]:
                    cur = math.gcd(cur, m)
                    if cur == g:
                        break
            if cur == g:
                ans += 1
        return ans

