var countDifferentSubsequenceGCDs = function(nums) {
    const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));
    const maxV = Math.max(...nums);
    const present = new Array(maxV + 1).fill(false);
    for (const x of nums) present[x] = true;
    let ans = 0;
    for (let g = 1; g <= maxV; g++) {
        let cur = 0;
        for (let m = g; m <= maxV; m += g) {
            if (present[m]) {
                cur = gcd(cur, m);
                if (cur === g) break;
            }
        }
        if (cur === g) ans++;
    }
    return ans;
};
